function init(){defaults({wrong:[],player:'玩家 A',round:null});state.custom??=[]}init();
function startRound(wrong=false){const source=wrong?p.wrong:[...state.questions,...state.custom];if(!source.length)return toast('现在没有错题，先去挑战吧');p.round={questions:clone(source),index:0,score:0,answer:null,finished:false};active=0;commit('新一轮开始啦');window.scrollTo({top:0,behavior:'instant'})}
function answer(bin){const r=p.round;if(!r||r.answer!==null||r.finished)return;const q=r.questions[r.index];r.answer=bin;if(bin===q.bin)r.score++;else if(!p.wrong.some(x=>x.name===q.name))p.wrong.push(clone(q));commit(bin===q.bin?'分对啦，看看为什么':'没关系，一起看看分类的理由')}
function editQuestion(index){const q=state.custom[+index];editModal('修改我的题目',field('物品和它的状态','name','text',q.name,'required maxlength="60"')+select('正确分类','bin',state.bins,q.bin)+textfield('为什么这样分','reason',q.reason,300),v=>{Object.assign(q,v);commit('题目已修改，下一轮生效')});$('#edit-form').insertAdjacentHTML('beforeend',btn('移除题目','remove-question','danger'));on('remove-question',()=>{state.custom.splice(+index,1);closeModal();commit('题目已移除，可撤销')})}
function render(){nav();const r=p.round;
if(active===0){if(!r){$('#app').innerHTML=`<div class="screen-body">${hero('让物品找到下一站','分类小侦探','观察物品的材料，也留意它现在的状态。','recycle')}<section class="card" style="margin-top:20px"><h2>一件物品，一次选择</h2><p class="hint" style="margin:16px 0 22px">共 ${state.questions.length+state.custom.length} 道题。选错也没关系，每道题都会告诉你原因。</p>${btn('开始挑战','start','primary full')}</section><p class="subtle" style="margin-top:18px">使用四分类练习规则；实际投放请按当地要求。分类看物品本身，也看是否干净、是否有害。</p></div>`;on('start',()=>startRound())}else if(r.finished){$('#app').innerHTML=`<div class="screen-body">${hero('这一轮，探索完成',`${r.score}<small>/ ${r.questions.length} 题</small>`,'每一个理解的理由，都比多一分更重要。','recycle')}<section class="card" style="margin-top:20px"><h2>做得不错，再试一次？</h2><p class="hint" style="margin:12px 0 20px">错题已放进“发现”，随时可以回去看看。</p><div class="stack">${btn('再挑战一次','start','primary full')}${btn('去看我的发现','review','secondary full')}</div></section></div>`;on('start',()=>startRound());on('review',()=>go(1))}else{const q=r.questions[r.index];$('#app').innerHTML=`<div class="screen-body"><div class="between"><span class="eyebrow">第 ${r.index+1} / ${r.questions.length} 题</span><span class="pill">已答对 ${r.score} 题</span></div>${progress(r.index/r.questions.length*100)}<section class="card quiz-card"><div class="quiz-object" aria-hidden="true">${esc(q.icon||'📦')}</div><h2>${esc(q.name)}</h2><p class="hint" style="margin-top:10px">它应该去哪个分类箱？</p></section><div class="bin-grid">${state.bins.map((b,i)=>`<button data-bin="${esc(b)}" style="--bin:${['#487fa2','#ae5446','#77834e','#6e7475'][i]}" ${r.answer!==null?'disabled':''} class="${r.answer!==null&&b===q.bin?'correct':''}">${icon('trash')}${esc(b)}</button>`).join('')}</div>${r.answer!==null?`<section class="notice ${r.answer===q.bin?'':'warning'}"><strong>${r.answer===q.bin?'分对了！':`应该放进“${esc(q.bin)}”`}</strong><p>${esc(q.reason)}</p></section><div style="margin-top:16px">${btn(r.index+1===r.questions.length?'查看本轮结果':'下一件物品','next','primary full')}</div>`:'<p class="hint" style="text-align:center">点一下分类箱，做出你的选择。</p>'}</div>`;actions('bin',answer);on('next',()=>{if(r.index+1===r.questions.length){r.finished=true;state.board.push({date:today(),score:r.score,total:r.questions.length,player:p.player})}else{r.index++;r.answer=null}commit('')})}}
if(active===1){$('#app').innerHTML=`<div class="two-col"><div>${heading('值得再想一想',btn('只练错题','wrong','',!p.wrong.length))}${list(p.wrong,q=>`<section class="card"><span class="pill">${esc(q.bin)}</span><h3 style="margin:12px 0">${esc(q.name)}</h3><p class="hint">${esc(q.reason)}</p></section>`)}</div><aside class="card"><h3>我的挑战记录</h3>${list([...state.board].reverse(),x=>`<div class="list-item"><div class="content"><strong>${x.score} / ${x.total||state.questions.length} 题</strong><p>${esc(x.date)}</p></div>${icon('flag')}</div>`)}</aside></div>`;on('wrong',()=>startRound(true))}
if(active===2){$('#app').innerHTML=`<div class="screen-body">${heading('当一次出题人')}<div class="notice">试试比较“干净纸盒”和“沾满油污的纸盒”。同一种材料，不同的状态，可能有不同答案。</div><section class="card" style="margin-top:20px"><form id="question" class="stack">${field('物品和它的状态','name','text','','required maxlength="60" placeholder="例如：沾满油污的纸盒"')}${select('正确分类','bin',state.bins)}${textfield('为什么这样分','reason','',300)}<button class="primary">加入我的题库</button></form></section>${list(state.custom,q=>`<div class="list-item"><div class="content"><strong>${esc(q.name)}</strong><p>${esc(q.bin)} · ${esc(q.reason)}</p></div><button data-editquestion="${state.custom.indexOf(q)}">修改</button></div>`)}</div>`;actions('editquestion',editQuestion);form('question',v=>{if([...state.questions,...state.custom].some(x=>x.name===v.name)){toast('题库里已经有这道题');return}state.custom.push({...v,icon:'📦'});commit('题目已加入，下一轮挑战就会出现')})}}
shell([['挑战','play'],['发现','leaf'],['出题','edit']]);render();
